   string path=Root+"Materials/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){var s=Shader.Find(shader);if(!s)throw new Exception("Missing shader "+shader);mat=new Material(s);AssetDatabase.CreateAsset(mat,path);}if(mat.HasProperty("_BaseColor"))mat.SetColor("_BaseColor",color);if(texture)mat.SetTexture("_BaseMap",texture);if(mat.HasProperty("_Surface")){mat.SetFloat("_Surface",1);mat.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);mat.SetFloat("_DstBlend",additive?(float)BlendMode.One:(float)BlendMode.OneMinusSrcAlpha);mat.SetFloat("_ZWrite",0);mat.SetFloat("_Cull",0);mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mat.renderQueue=3000;}EditorUtility.SetDirty(mat);return mat;
