  static void Collide(ParticleSystem p,float bounce){var c=p.collision;c.enabled=true;c.type=ParticleSystemCollisionType.World;c.mode=ParticleSystemCollisionMode.Collision3D;c.quality=ParticleSystemCollisionQuality.High;c.enableDynamicColliders=true;c.bounce=bounce;c.dampen=.55f;c.lifetimeLoss=0;c.radiusScale=.6f;c.collidesWith=~0;}
