   foreach(var guid in AssetDatabase.FindAssets("t:Texture2D",new[]{Root+"Textures"})){string path=AssetDatabase.GUIDToAssetPath(guid);var imp=(TextureImporter)AssetImporter.GetAtPath(path);bool normal=path.Contains("_Normal"),data=normal||path.Contains("_AO")||path.Contains("_Height")||path.Contains("_Mask")||path.Contains("Noise");imp.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;imp.sRGBTexture=!data;imp.maxTextureSize=path.Contains("Smoke")?2048:2048;imp.wrapMode=path.Contains("Crater")?TextureWrapMode.Clamp:TextureWrapMode.Repeat;imp.alphaIsTransparency=!data;imp.mipmapEnabled=true;imp.SaveAndReimport();}
  }
  static void Boss(GameObject root,GameObject steam,GameObject lightning,GameObject[] decals)
