   var boss=root.GetComponent<UDK7MBoss>();if(!boss)return;var vfx=root.GetComponent<BossVFXController>();if(!vfx)vfx=root.AddComponent<BossVFXController>();vfx.boss=boss;vfx.steamPrefab=steam;vfx.lightningPrefab=lightning;
