   var surface=root.transform.Find("VFX Surface Sockets");if(!surface){surface=new GameObject("VFX Surface Sockets").transform;surface.SetParent(root.transform,false);foreach(var p in new[]{new Vector3(-1,2.2f,0),new Vector3(1,2.2f,0),new Vector3(-.8f,3.2f,-.5f),new Vector3(.8f,3.2f,-.5f),new Vector3(0,3.9f,0),new Vector3(-1.5f,1.2f,0),new Vector3(1.5f,1.2f,0)}){var t=new GameObject("Surface arc "+surface.childCount).transform;t.SetParent(surface,false);t.localPosition=p;}}vfx.surfaceSockets=surface.GetComponentsInChildren<Transform>();
   var stamp=root.GetComponent<GroundImpactDecals>();if(!stamp)stamp=root.AddComponent<GroundImpactDecals>();stamp.prefabs=decals;
  }
