    var ringMat=Mat("ChromaticShockRing",shader.name,Color.white);ringMat.SetFloat("_Mode",0);ringMat.SetFloat("_Distortion",.045f);ringMat.SetFloat("_Chromatic",.008f);var shellMat=Mat("ChromaticShockShell",shader.name,Color.white);shellMat.SetFloat("_Mode",1);shellMat.SetFloat("_Distortion",.025f);shellMat.SetFloat("_Chromatic",.004f);var heatMat=Mat("TankHeatHaze",shader.name,Color.white);heatMat.SetFloat("_Mode",2);heatMat.SetFloat("_Distortion",.014f);heatMat.SetFloat("_Chromatic",0);
    var spark=new GameObject("Sparks");var gpu=new GameObject("GPU Burst 56");gpu.transform.SetParent(spark.transform,false);gpu.AddComponent<VisualEffect>().visualEffectAsset=Load<VisualEffectAsset>("Graphs/SparkBurst.vfx");spark.AddComponent<VFXGroundBinder>();var streak=PS(spark,"World collision streaks",sparkMaterial,18,.9f,11,.035f,new Color(4,1.8f,.25f,1));var sm=streak.main;sm.gravityModifier=1.1f;Collide(streak,.4f);var sr=streak.GetComponent<ParticleSystemRenderer>();sr.renderMode=ParticleSystemRenderMode.Stretch;sr.velocityScale=.18f;sr.lengthScale=3;var flash=new GameObject("Orange flash no shadows");flash.transform.SetParent(spark.transform,false);var light=flash.AddComponent<Light>();light.type=LightType.Point;light.color=new Color(1,.35f,.035f);light.range=3;light.shadows=LightShadows.None;flash.AddComponent<VFXLightPulse>().point=light;var sparkPrefab=Save(spark,"Sparks");
