  static void Preview(GameObject shock,GameObject steam,GameObject lightning,GameObject decal)
  {
   var s=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(s);try{var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.name="Review concrete ground";floor.transform.position=new Vector3(0,-.15f,1);floor.transform.localScale=new Vector3(28,.3f,25);var floorMat=Mat("ReviewFloor","Universal Render Pipeline/Lit",Color.white);Opaque(floorMat);string checkerPath=Root+"Preview/ReviewChecker.asset";var checker=Load<Texture2D>("Preview/ReviewChecker.asset");if(!checker){checker=new Texture2D(64,64){name="Refraction review checker",wrapMode=TextureWrapMode.Repeat,filterMode=FilterMode.Bilinear};for(int y=0;y<64;y++)for(int x=0;x<64;x++)checker.SetPixel(x,y,((x/8+y/8)%2==0)?new Color(.45f,.47f,.5f):new Color(.12f,.14f,.17f));checker.Apply();AssetDatabase.CreateAsset(checker,checkerPath);}floorMat.SetTexture("_BaseMap",checker);floorMat.SetTextureScale("_BaseMap",new Vector2(4,4));floor.GetComponent<Renderer>().sharedMaterial=floorMat;var sun=new GameObject("Review key light").AddComponent<Light>();sun.type=LightType.Directional;sun.transform.rotation=Quaternion.Euler(45,-30,0);sun.intensity=1.2f;RenderSettings.ambientLight=new Color(.18f,.2f,.24f);var camera=new GameObject("Main Camera").AddComponent<Camera>();camera.tag="MainCamera";camera.transform.SetPositionAndRotation(new Vector3(9,6,-12),Quaternion.LookRotation(new Vector3(-9,-4,13)));camera.fieldOfView=55;camera.nearClipPlane=.05f;camera.farClipPlane=120;camera.GetUniversalAdditionalCameraData().requiresColorTexture=true;camera.GetUniversalAdditionalCameraData().requiresDepthTexture=true;camera.GetUniversalAdditionalCameraData().renderPostProcessing=true;var volume=new GameObject("Review bloom").AddComponent<Volume>();volume.isGlobal=true;var profile=Load<VolumeProfile>("Preview/ReviewVolume.asset");if(!profile){profile=ScriptableObject.CreateInstance<VolumeProfile>();profile.Add<Bloom>().intensity.Override(.7f);AssetDatabase.CreateAsset(profile,Root+"Previ